import json,re,urllib.request
def spec(slug):
    t=urllib.request.urlopen('https://developer.jamf.com/jamf-pro/reference/%s.md'%slug).read().decode()
    return json.loads(re.search(r'```json\s*(\{.*\})\s*```',t,re.S).group(1))
def props(d,name,depth=0):
    s=d['components']['schemas'][name]
    out={}
    for k,v in s.get('properties',{}).items():
        out[k]=v.get('type') or v.get('$ref','').split('/')[-1]
        if 'enum' in v: out[k]+=' '+str(v['enum'])
    return out
for slug,path in [('get_v1-cloud-information','/v1/cloud-information'),('get_v3-mobile-device-prestages','/v3/mobile-device-prestages'),('get_v1-notifications','/v1/notifications'),('get_v1-user-sessions-active','/v1/user-sessions/active')]:
    try:
        d=spec(slug)
    except Exception as e:
        print(slug,'ERR',e); continue
    op=d['paths'][path]['get']
    print('==',path, op.get('description','').replace('\n',' ')[:250])
    for code,r in op['responses'].items():
        c=r.get('content',{}).get('application/json',{}).get('schema',{})
        ref=c.get('$ref') or c.get('items',{}).get('$ref')
        if ref:
            n=ref.split('/')[-1]; p=props(d,n); print(code,n,p)
            for k,v in list(p.items()):
                if v=='array':
                    it=d['components']['schemas'][n]['properties'][k].get('items',{}).get('$ref')
                    if it: print('  ',k,'->',props(d,it.split('/')[-1]))
EOF

